#include <stdio.h>

static long cmp_count = 0, move_count = 0;

void shell_sort(int a[], int n) {
    /* 经典 Shell 步长序列：n/2, n/4, ..., 1 */
    for (int gap = n / 2; gap > 0; gap /= 2) {
        printf("步长 gap=%d\n", gap);
        for (int i = gap; i < n; i++) {
            int x = a[i];
            move_count++;
            int j = i;
            while (j >= gap) {
                cmp_count++;
                if (a[j - gap] > x) {
                    a[j] = a[j - gap];
                    move_count++;
                    j -= gap;
                } else break;
            }
            a[j] = x;
            move_count++;
        }
        printf("  本趟后:");
        for (int k = 0; k < n; k++) printf(" %d", a[k]);
        printf("\n");
    }
}

int main(void) {
    int a[] = {49, 38, 65, 97, 76, 13, 27, 49, 55, 4};
    int n = (int)(sizeof(a) / sizeof(a[0]));

    printf("原始序列:");
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n\n");

    shell_sort(a, n);

    printf("\n最终结果:");
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n");
    printf("比较次数 = %ld, 移动次数 = %ld\n", cmp_count, move_count);
    printf("直接插入排序在同样数据上的比较次数通常明显更多 -> 希尔靠大步长提前消除逆序\n");
    printf("不稳定的原因: 不同步长下的跨距离移动会打乱等值元素的相对顺序\n");
    return 0;
}
